	template <class T> static const void* NextOf(Ser& s, const char* name, const void* at) {
		T* item = s.Writing() ? (T*)at : s.Memory()->Array<T>(1);
		if (s.Reading()) item->sType = (VkStructureType)0;
		s.Field(name, *item);
		return item;
	}

